Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB0RA_1LC1RA_1LD0LC_1RA1LA : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB0RA_1LC1RA_1LD0LC_1RA1LA. Qed.

