                           nrules vsegs_1RB0RA_1LC1RA_1LD0LC_1RA1LA vis_1RB0RA_1LC1RA_1LD0LC_1RA1LA
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
