    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; reflexivity. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; split; [lia | split; [lia | reflexivity]]. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0RA_1LC1RA_1LD0LC_1RA1LA.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - vm_compute; reflexivity.
  - exact aarm_reach_1RB0RA_1LC1RA_1LD0LC_1RA1LA.
  - exact aarm_lhs_1RB0RA_1LC1RA_1LD0LC_1RA1LA.
